import sys

class N:
    __slots__ = ('v', 'nxt', 'rnd')
    def __init__(self, v=0, nxt=None, rnd=None):
        self.v = v; self.nxt = nxt; self.rnd = rnd

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    values = []
    idx = 1
    for _ in range(n):
        values.append((int(data[idx]), int(data[idx + 1])))
        idx += 2
    if n == 0:
        sys.exit(0)
    orig = [N(vs[0]) for vs in values]
    new_nodes = [N(vs[0]) for vs in values]
    mapping = {id(orig[i]): new_nodes[i] for i in range(n)}
    for i in range(n - 1):
        orig[i].nxt = orig[i + 1]
        new_nodes[i].nxt = new_nodes[i + 1]
    for i, (_, r) in enumerate(values):
        if r >= 0:
            orig[i].rnd = orig[r]
            new_nodes[i].rnd = mapping[id(orig[r])]
        else:
            new_nodes[i].rnd = None
    out = []
    for i, nd in enumerate(new_nodes):
        nxt = new_nodes[i + 1] if i + 1 < n else None
        rnd = nd.rnd
        out.append(str(nd.v) + ' ' + (str(nxt.v) if nxt else 'n') + ' ' + (str(rnd.v) if rnd else 'n'))
    print(chr(10).join(out))

import sys

class N:
    __slots__ = ('v', 'nxt', 'rnd')
    def __init__(self, v=0, nxt=None, rnd=None):
        self.v = v; self.nxt = nxt; self.rnd = rnd

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    values = []
    idx = 1
    for _ in range(n):
        v = int(data[idx]); r = int(data[idx + 1])
        values.append((v, r))
        idx += 2
    if n == 0:
        sys.exit(0)
    orig = [N(vs[0]) for vs in values]
    mapping = {orig[i]: N(values[i][0]) for i in range(n)}
    for i in range(n - 1):
        orig[i].nxt = orig[i + 1]
        mapping[orig[i]].nxt = mapping[orig[i + 1]]
    for i, (_, r) in enumerate(values):
        if r >= 0:
            orig[i].rnd = orig[r]
        mapping[orig[i]].rnd = mapping[orig[r]] if r >= 0 else None
    res = [mapping[orig[i]] for i in range(n)]
    out = []
    for i, nd in enumerate(res):
        nxt = res[i + 1] if i + 1 < len(res) else None
        rnd = nd.rnd
        out.append(f'{nd.v} {nxt.v if nxt else "n"} {rnd.v if rnd else "n"}')
    print('\n'.join(out))
